components.css:
.ds-select { position: relative; display: inline-flex; min-width: 0; vertical-align: middle; }
.ds-select-control { font-family:var(--font-jakarta,'Plus Jakarta Sans'),Arial,Helvetica,sans-serif; appearance: none; width: 100%; min-width: 0; min-height: 44px; padding: 11px 42px 11px 14px; border: 1px solid var(--control-border,#9aaa9c); border-radius: 12px; background: var(--surface,#fff); color: var(--foreground,#263d30); font-size: 13px; line-height: 1.5; font-weight: 600; cursor: pointer; white-space: nowrap; text-overflow: ellipsis; overflow: hidden; }
.ds-select-control:hover:not(:disabled) { border-color: var(--green,#007e5c); background: var(--green-light,#edf7e8); }
.ds-select-control:focus-visible { outline: 2px solid var(--green,#007e5c); outline-offset: 3px; border-color: var(--green,#007e5c); }
.ds-select-control:disabled { opacity: .55; cursor: not-allowed; }
.ds-select-chevron { position: absolute; right: 14px; top: 50%; translate: 0 -50%; color: var(--green,#007e5c); pointer-events: none; transition: rotate .18s cubic-bezier(.16, 1, .3, 1); }
.ds-select:has(select:open) .ds-select-chevron { rotate: 180deg; }


@supports (appearance: base-select) {
  .ds-select-control, .ds-select-control::picker(select) { appearance: base-select; }
  .ds-select-control::picker-icon { display: none; }
  .ds-select-control:open { border-color: var(--green,#007e5c); }
  .ds-select-control::picker(select) { min-width: anchor-size(width); max-height: min(320px, 65dvh); margin-block: 6px; padding: 6px; border: 1px solid var(--control-border,#9aaa9c); border-radius: 14px; background: var(--surface,#fff); color: var(--foreground,#263d30); font: inherit; overflow: auto; scrollbar-color: #9aafa2 transparent; scrollbar-width: thin; }
  .ds-select-control option { min-height: 44px; display: flex; align-items: center; gap: 12px; padding: 10px 12px; border-radius: 8px; white-space: normal; overflow-wrap: anywhere; font-weight: 500; cursor: pointer; }
  .ds-select-control option:hover { background: var(--control-hover,#f2f5ed); }
  .ds-select-control option:checked { background: var(--green-light,#edf7e8); color: var(--green,#007e5c); font-weight: 700; }
  .ds-select-control option:focus-visible { outline: 2px solid var(--green,#007e5c); outline-offset: -2px; }
  .ds-select-control option::checkmark { order: 1; margin-left: auto; color: var(--green,#007e5c); }
}
@media (max-width: 640px) {
  .ds-select-control { font-size: 16px; padding-inline: 12px 32px; }
  .ds-select-chevron { right: 10px; width: 15px; }
}
@media (prefers-reduced-motion: reduce) { .ds-select-chevron { transition: none; } }
